    //   A[i][j] with i in [0..m-1], j in [0..n-1]
    //   x[j]     with j in [0..n-1]
    //
    // Halide layout (rule 1: first dimension is fastest-varying):
    //   A(j, i) with Buffer shape (n, m)
    //   x(j)    with Buffer shape (n)

    Var i("i"), j("j");

    Func init_A("init_A"), init_x("init_x");

    // We'll use a 32-bit int literal and cast explicitly to num_t.
    Expr fn   = cast<num_t>(Expr(n));
    Expr one  = cast<num_t>(Expr(1));

    // x[j] = 1 + (j / fn);
    {
        Expr j_f = cast<num_t>(j);
        init_x(j) = one + j_f / fn;
    }

    // A[i][j] = (DATA_TYPE)((i + j) % n) / (5*m);
    // Our layout is A(j,i), with shape (n, m).
    {
        Expr num   = cast<num_t>((i + j) % n);
        Expr denom = cast<num_t>(Expr(5 * m));
        init_A(j, i) = num / denom;
    }

    // -------------------------------------------------------------------------
    // Schedule for initialization
    //
    // We only do this once, but it still pays to give a simple
    // vectorized + parallel schedule, especially for large M,N.
    // -------------------------------------------------------------------------
    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // Initialize x in parallel, vectorizing along the contiguous j dimension.
    {
        Var jo("jo"), ji("ji");
        init_x
            .split(j, jo, ji, vec_width)
            .parallel(jo)
            .vectorize(ji);
    }

    // Initialize A in tiles over (j, i) to keep j (dim 0) contiguous.
    {
        Var jo("jo"), ji("ji"), io("io");
        const int tile_j = 64;  // small tile for cache locality; can be tuned

        init_A
            .split(j, jo, ji, tile_j)  // j = jo * tile_j + ji
            .reorder(ji, i, jo)        // inner loops: ji (contiguous in memory), then i
            .parallel(i)               // parallelize over rows (i)
            .vectorize(ji, vec_width);
    }

    // Realize into the provided Buffers
    init_x.realize(x);
    init_A.realize(A);
}

// -----------------------------------------------------------------------------
// Main
// -----------------------------------------------------------------------------
int main(int argc, char *argv[]) {
    // Problem size (from atax.hpp / defines.hpp)
    int m = M;
    int n = N;

    // Buffers:
    // A(i,j) in C becomes A(j,i) with shape (n, m) in Halide.
    Halide::Buffer<num_t, 2> A(n, m);  // [j, i]
    Halide::Buffer<num_t, 1> x(n);     // [j]
    Halide::Buffer<num_t, 1> y(n);     // [j] output

    // Initialize data
    init_array(m, n, A, x);

    // Wrap A and x as ImageParams so the pipeline is decoupled from
    // the concrete Buffers and can be JIT-compiled independently.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam x_param(type_of<num_t>(), 1, "x_param");

    // Vars and reduction domains
    Var i("i"), j("j");

    // Use the runtime extents of A to define the reduction ranges,
    // mirroring the original C loops over N and M.
    //
    // A has shape (n, m) as [j, i], so:
    //   dim(0).extent() == n   (j in [0..n-1])
    //   dim(1).extent() == m   (i in [0..m-1])
    RDom r1(0, A.dim(0).extent(), "r1");  // corresponds to j in [0..n-1]
    RDom r2(0, A.dim(1).extent(), "r2");  // corresponds to i in [0..m-1]

    // -------------------------------------------------------------------------
    // Kernel translation
    //
    // Original C kernel:
    //
    //   for (i = 0; i < _PB_N; i++)
    //     y[i] = 0;
    //   for (i = 0; i < _PB_M; i++) {
    //     tmp[i] = 0;
    //     for (j = 0; j < _PB_N; j++)
    //       tmp[i] = tmp[i] + A[i][j] * x[j];
    //     for (j = 0; j < _PB_N; j++)
    //       y[j] = y[j] + A[i][j] * tmp[i];
    //   }
    //
    // This is:
    //   tmp[i] = sum_j A[i][j] * x[j];
    //   y[j]   = sum_i A[i][j] * tmp[i];
    //
    // With our layout A(j,i):
    //   tmp(i) = sum_j A(j,i) * x(j);
    //   y(j)   = sum_i A(j,i) * tmp(i);
    // -------------------------------------------------------------------------
    Func tmp("tmp"), y_func("y_func");

    // tmp(i) = sum over r1 (j) of A(j,i) * x(j)
    tmp(i) = cast<num_t>(Expr(0));
    tmp(i) += A_param(r1, i) * x_param(r1);

    // y(j) = sum over r2 (i) of A(j,i) * tmp(i)
    y_func(j) = cast<num_t>(Expr(0));
    y_func(j) += A_param(j, r2) * tmp(r2);

    // -------------------------------------------------------------------------
    // Schedule
    //
    // Design goals:
    //   - Preserve the original algorithm exactly.
    //   - Keep accesses to A contiguous where possible.
    //   - Exploit parallelism across independent indices.
    //   - Use vectorization on contiguous dimensions.
    // -------------------------------------------------------------------------

    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());
    const int tmp_parallel_grain = 64;  // tuning knob for tmp parallelism

    // -----------------------------
    // Schedule for tmp
    // -----------------------------
    //
    // tmp(i) is a 1D reduction over j:
    //   tmp(i) = sum_j A(j,i) * x(j)
    //
    // For each i, the reduction reads a contiguous row of A in j:
    //   A(j, i) with j in dim(0) (fastest-varying).
    // This is already cache-friendly. We parallelize across i, mimicking
    // the outer loop over M in the original C code.
    tmp.compute_root();

    {
        Var io("io"), ii("ii");

        // Pure step (tmp(i) = 0) – cheap, but keep the same tiling
        // to align with the update step.
        tmp
            .split(i, io, ii, tmp_parallel_grain)
            .parallel(io);

        // Update step (the reduction).
        // Each i (and therefore each ii within a tile) is independent,
        // so we can parallelize over io safely.
        tmp.update()
            .split(i, io, ii, tmp_parallel_grain)
            .parallel(io);
    }

    // -----------------------------
    // Schedule for y_func
    // -----------------------------
    //
    // y(j) = sum_i A(j,i) * tmp(i)
    //
    // For fixed i, iterating j gives contiguous access to A(j,i) and y(j).
    // We mimic the original loop order:
    //   for (i = 0; i < M; i++)
    //     for (j = 0; j < N; j++)
    //       y[j] += A[i][j] * tmp[i];
    //
    // by making j the innermost loop and i (r2) outer.
    // We vectorize along j (dim 0), which is contiguous.
    y_func.compute_root();

    {
        // Initialize y in parallel and vectorized across j.
        Var jo("jo"), ji("ji");
        y_func
            .split(j, jo, ji, vec_width)
            .parallel(jo)
            .vectorize(ji);

        // Reduction update:
        //   r2 (i) outermost, j inner and vectorized.
        //   This preserves good locality on A(j,i) and y(j).
        y_func.update()
            .reorder(j, r2);       // innermost j, outermost r2
        y_func.update()
            .split(j, jo, ji, vec_width)
            .reorder(ji, jo, r2)   // innermost ji (vector), then jo, then r2
            .vectorize(ji);
        // We deliberately do not parallelize the update across j or r2:
        // parallelizing across r2 would introduce races on y(j),
        // and nested parallelism over j for every i often hurts more
        // than it helps for this simple kernel. Parallelism is instead
        // provided by tmp's compute_root() stage.
    }

    // Bind actual Buffers to the ImageParams
    A_param.set(A);
    x_param.set(x);

    // JIT-compile the kernel for the chosen target
    y_func.compile_jit(target);

    // -------------------------------------------------------------------------
    // Run and time the kernel
    // -------------------------------------------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: realize y_func into y buffer
    y_func.realize(y);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // -------------------------------------------------------------------------
    // Print results (to prevent dead-code elimination and for checking)
    // -------------------------------------------------------------------------
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int idx = 0; idx < n; idx++) {
            std::cerr << y(idx) << '\n';
        }
    }

    // Print execution time in seconds (like gemm.cpp)
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
