#include "Halide.h"

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "atax.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

// -----------------------------------------------------------------------------
// Tunable scheduling constants
// -----------------------------------------------------------------------------
constexpr int VEC_WIDTH = 8;      // Vector width for SIMD over the innermost loop
constexpr int Y_CHUNK   = 256;    // Number of y-elements per parallel chunk
constexpr int INIT_X_CHUNK = 256; // Chunk size for init_x parallelization
constexpr int INIT_A_CHUNK_I = 32;

// -----------------------------------------------------------------------------
// Array initialization translated to Halide
// -----------------------------------------------------------------------------
static void init_array(int m, int n,
                       Halide::Buffer<num_t, 2> A,  // shape: [n, m]  (j, i)
                       Halide::Buffer<num_t, 1> x)  // shape: [n]     (j)
{
    // C layout:
    //   A[i][j] with i in [0..m-1], j in [0..n-1]
    //   x[j]     with j in [0..n-1]
    //
    // Halide layout (rule 1: first dimension is fastest-varying):
    //   A(j, i) with Buffer shape (n, m)
    //   x(j)    with Buffer shape (n)

    Var i("i"), j("j");
    Var xo("xo"), xi("xi");
    Var io("io"), ii("ii");

    Func init_A("init_A"), init_x("init_x");

    // fn = (DATA_TYPE)n;
    Expr fn = cast<num_t>(Expr(n));

    // for (j = 0; j < n; j++)
    //     x[j] = 1 + (j / fn);
    {
        Expr one = cast<num_t>(Expr(1));
        Expr j_f = cast<num_t>(j);
        init_x(j) = one + j_f / fn;

        // Schedule for x initialization:
        // - Parallelize across large chunks of j.
        // - Vectorize within each chunk.
        init_x
            .split(j, xo, xi, INIT_X_CHUNK)
            .parallel(xo)
            .vectorize(xi, VEC_WIDTH);
    }

    // for (i = 0; i < m; i++)
    //   for (j = 0; j < n; j++)
    //     A[i][j] = (DATA_TYPE)((i + j) % n) / (5*m);
    {
        Expr num   = cast<num_t>((i + j) % n);
        Expr denom = Expr(5 * m);  // promoted to num_t automatically
        init_A(j, i) = num / denom;

        // Schedule for A initialization:
        // - Parallelize over the (slower-varying) i dimension (rows in C layout).
        // - Vectorize across j (fastest-varying, contiguous in memory).
        init_A
            .split(i, io, ii, INIT_A_CHUNK_I)
            .parallel(io)
            .vectorize(j, VEC_WIDTH);
    }

    // Realize into the provided Buffers
    init_x.realize(x);
    init_A.realize(A);
}

// -----------------------------------------------------------------------------
// Main
// -----------------------------------------------------------------------------
int main(int argc, char *argv[]) {
    // Problem size (from atax.hpp / defines.hpp)
    int m = M;
    int n = N;

    // Buffers:
    // A(i,j) in C becomes A(j,i) with shape (n, m) in Halide.
    Halide::Buffer<num_t, 2> A(n, m);  // [j, i]
    Halide::Buffer<num_t, 1> x(n);     // [j]
    Halide::Buffer<num_t, 1> y(n);     // [j] output

    // Initialize data
    init_array(m, n, A, x);

    // Wrap A and x as ImageParams so the pipeline is decoupled from
    // the concrete Buffers and can be JIT-compiled independently.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam x_param(type_of<num_t>(), 1, "x_param");

    // Assume standard row-major layout for the input buffers:
    //   A(j,i): j contiguous; x(j): contiguous.
    // These constraints let Halide generate better code (no need to
    // handle arbitrary strides).
    A_param.dim(0).set_stride(1); // j
    x_param.dim(0).set_stride(1); // j

    // Vars and reduction domains
    Var i("i"), j("j");

    // Use the ImageParam dimensions to define the reduction ranges so
    // that the pipeline is not hard-wired to compile-time sizes.
    //
    // r1: corresponds to j in [0..n-1]
    // r2: corresponds to i in [0..m-1]
    RDom r1(0, A_param.dim(0).extent(), "r1");
    RDom r2(0, A_param.dim(1).extent(), "r2");

    // -------------------------------------------------------------------------
    // Kernel translation
    //
    // Original C kernel:
    //
    //   for (i = 0; i < _PB_N; i++)
    //     y[i] = 0;
    //   for (i = 0; i < _PB_M; i++) {
    //     tmp[i] = 0;
    //     for (j = 0; j < _PB_N; j++)
    //       tmp[i] = tmp[i] + A[i][j] * x[j];
    //     for (j = 0; j < _PB_N; j++)
    //       y[j] = y[j] + A[i][j] * tmp[i];
    //   }
    //
    // This is:
    //   tmp[i] = sum_j A[i][j] * x[j];
    //   y[j]   = sum_i A[i][j] * tmp[i];
    //
    // With our layout A(j,i):
    //   tmp(i) = sum_j A(j,i) * x(j);
    //   y(j)   = sum_i A(j,i) * tmp(i);
    // -------------------------------------------------------------------------
    Func tmp("tmp"), y_func("y_func");

    // tmp(i) = sum over r1 (j) of A(j,i) * x(j)
    tmp(i) = cast<num_t>(Expr(0));
    tmp(i) += A_param(r1, i) * x_param(r1);

    // y(j) = sum over r2 (i) of A(j,i) * tmp(i)
    y_func(j) = cast<num_t>(Expr(0));
    y_func(j) += A_param(j, r2) * tmp(r2);

    // -------------------------------------------------------------------------
    // Schedule
    // -------------------------------------------------------------------------
    Target target = get_host_target();

    // Bind actual Buffers to the ImageParams before specializing on layout.
    A_param.set(A);
    x_param.set(x);

    // ----------------------
    // Schedule for tmp(i)
    // ----------------------
    //
