    //   y(j)   = sum_i A(j,i) * tmp(i);    (A^T * tmp)
    // -------------------------------------------------------------------------
    Func tmp("tmp"), y_func("y_func");

    // tmp(i) = sum over rj (j) of A(j,i) * x(j)
    tmp(i) = cast<num_t>(Expr(0));
    tmp(i) += A_param(rj, i) * x_param(rj);

